'use strict';
const priorTimedAct=act;
const travelOverlay=document.createElement('dialog');travelOverlay.id='timeTransition';travelOverlay.setAttribute('aria-label','Kalenderen går fremover');document.body.append(travelOverlay);
let timeFrame=0;
const calendarDate=d=>new Date(Date.UTC(2026,0,1+d)).toLocaleDateString('nb-NO',{day:'numeric',month:'long',year:'numeric',timeZone:'UTC'});
function closeTime(){cancelAnimationFrame(timeFrame);if(travelOverlay.open)travelOverlay.close();}
function showTime(from,to,type,origin){if(to<=from||localStorage.getItem('vestkyst-animations')==='off'||matchMedia('(prefers-reduced-motion: reduce)').matches)return;closeTime();const days=to-from,title=['tripBuy','continueTrip'].includes(type)?'STAVANGER ↔ '+G.ORIGINS[origin||0].place.toUpperCase():type==='streetSell'?'SALGSDAGENE GÅR':type==='rest'?'BYEN GÅR VIDERE MENS DU HVILER':'UKENE SETTER SPOR';
travelOverlay.innerHTML=`<div class="calendar-travel"><span class="section-kicker">${title}</span><div class="calendar-path"><span>STAVANGER</span><i></i><span>${['tripBuy','continueTrip'].includes(type)?G.ORIGINS[origin||0].name.toUpperCase():'NESTE AVGJØRELSE'}</span></div><strong id="countingDate">${calendarDate(from)}</strong><p><b id="countingDays">0</b> av ${days} faktiske dager</p><div class="meter"><i id="countingBar" style="width:0%"></i></div><p>${s.trip?'Reisen stopper ved en avgjørelse. '+s.trip.remaining+' reisedager gjenstår.':s.event?'En viktig avgjørelse venter.':'Driften er gjort opp. Du er tilbake ved bordet.'}</p><button class="button brass" id="skipCalendar">Hopp over →</button></div>`;travelOverlay.showModal();$('#skipCalendar').onclick=closeTime;const start=performance.now(),duration=Math.min(1600,500+Math.log2(days+1)*150);function frame(now){const t=Math.min(1,(now-start)/duration),n=Math.min(days,Math.floor(days*(1-Math.pow(1-t,2))));$('#countingDate').textContent=calendarDate(from+n);$('#countingDays').textContent=n;$('#countingBar').style.width=(t*100)+'%';if(t<1)timeFrame=requestAnimationFrame(frame);else timeFrame=requestAnimationFrame(closeTime);}timeFrame=requestAnimationFrame(frame);
}
act=function(type,arg){const before=s.day,origin=type==='tripBuy'?arg?.origin:s.trip?.origin,result=priorTimedAct(type,arg);showTime(before,s.day,type,origin);return result;};
travelOverlay.addEventListener('cancel',closeTime);
const priorTimeSettings=$('#settings').onclick;$('#settings').onclick=()=>{priorTimeSettings();$('#dialogBody').insertAdjacentHTML('beforeend',`<hr><label class="check-label"><input id="timeAnimationToggle" type="checkbox" ${localStorage.getItem('vestkyst-animations')!=='off'?'checked':''}> Vis korte kalenderoverganger</label>`);$('#timeAnimationToggle').onchange=e=>localStorage.setItem('vestkyst-animations',e.target.checked?'on':'off');};
